<?php require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/layout.php'; $user=require_permission('view_all_tickets');
$tickets=db()->query("SELECT t.*,d.name department,a.full_name assignee FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN users a ON a.id=t.assignee_id WHERE t.deleted_at IS NULL ORDER BY t.updated_at DESC")->fetchAll();
$status=['open'=>'Open','in_progress'=>'In Progress','pending'=>'Pending','closed'=>'Closed']; page_start('Issues register',$user); ?>
<div class="page-head"><div><p class="eyebrow">CNG / Jamesons</p><h1>Issues register</h1><p class="page-subtitle">Shared account concerns and escalations.</p></div><div class="page-head-actions"><?php if(user_can('export_tickets')):?><a class="button button-secondary" href="export-tickets.php?format=csv">Export CSV</a><a class="button button-secondary" href="export-tickets.php?format=xlsx">Export Excel</a><?php endif;?><?php if(user_can('create_tickets')):?><a class="button" href="create-ticket.php">Create ticket</a><?php endif;?></div></div><div class="table-wrap"><table class="ticket-table"><thead><tr><?php foreach(['Status','Subject','Department','Category','Subcategory','Date Created','Date Updated','Date Closed','Assignee','Employee'] as $heading):?><th><?=e($heading)?></th><?php endforeach;?><th aria-label="Open ticket"></th></tr></thead><tbody><?php foreach($tickets as $ticket):?><tr><td><span class="pill pill-<?=e(str_replace('_','-',$ticket['status']))?>"><?=e($status[$ticket['status']])?></span></td><td class="subject"><a href="ticket.php?id=<?=$ticket['id']?>"><?=e($ticket['subject'])?></a></td><td><?=e($ticket['department'])?></td><td><?=e($ticket['category'])?></td><td><?=e($ticket['subcategory'] ?? '—')?></td><td class="muted"><?=e($ticket['created_at'])?></td><td class="muted"><?=e($ticket['updated_at'])?></td><td class="muted"><?=e($ticket['closed_at'] ?? '—')?></td><td><?=e($ticket['assignee'] ?? 'Unassigned')?></td><td><?=e($ticket['employee_name'])?></td><td class="row-arrow"><a href="ticket.php?id=<?=$ticket['id']?>" aria-label="Open <?=e($ticket['ticket_number'])?>">›</a></td></tr><?php endforeach; if(!$tickets):?><tr><td colspan="11" class="muted">No tickets have been created yet.</td></tr><?php endif;?></tbody></table></div><?php page_end();
